def lexical_entries(language):
    entries, glosses = build_entries(language, PLACES | PEOPLE, SENSES, set(PLACES))
    form = quantity(8, "ordinal")["form"] + " " + language.lexicon["month"]["form"]
    entries["august_month"] = dict(form=form, roman=language.reading(form), pos="noun",
        meaning="August, the eighth month in the source calendar. The day within it is the spoken tenth.",
        origin="Source-calendar reference using the Unta ordinal eight and the native month term.",
        semanticId="lex.august_month", usageScope="later-standard", status="authored",
        historicalForms=[], sourceCalendarMonth=8)
    glosses["august_month"] = "August"
    return entries, glosses


def prepare():
    add_source_entries("henry-vi-part-1", "henry-v", lexical_entries,
                       "Preserve the three messengers, the rival funeral interpretations, and Talbot's capture alive. Fastolf is distinct from Falstaff.")


if __name__ == "__main__":
    prepare()
